import numpy as np

def feature(item, bins, capacity):
    """Two columns: remaining-room fraction of each bin, and a fresh-bin indicator (1 for the last candidate)."""
    bins = np.asarray(bins, dtype=float)
    cap = float(capacity) if capacity else 1.0
    room = bins / cap
    fresh = np.zeros(bins.shape[0], dtype=float)
    if bins.shape[0] > 0:
        fresh[-1] = 1.0
    return np.stack([room, fresh], axis=1)

import numpy as np

def feature(item, bins, capacity):
    """Negative tent penalty on post-placement leftover in [0, 0.25] of capacity, peaking at 0.125."""
    x = np.clip((bins - item) / capacity, 0.0, 1.0)
    y = np.clip(x / 0.25, 0.0, 1.0)
    return -4.0 * y * (1.0 - y)

import numpy as np

def feature(item, bins, capacity):
    """Step score of post-placement leftover: +1 if rem<=0.02, -1 if rem<thr, else +0.5."""
    rem = (bins - item) / capacity
    thr = item / capacity
    return np.where(rem <= 0.02, 1.0, np.where(rem < thr, -1.0, 0.5))

import numpy as np

def feature(item, bins, capacity):
    """Negative post-placement residual scaled by (1 - crowdedness), crowdedness = mean Gaussian kernel density of residuals with width 0.15, with the self-term excluded from the density so the discount reflects only other candidates."""
    rem = (bins - item) / capacity
    k = rem.shape[0]
    diff = (rem[:, None] - rem[None, :]) / 0.15
    K = np.exp(-(diff ** 2))
    # exclude each candidate's own contribution (self-term = 1) from its density
    if k > 1:
        D = (K.sum(axis=1) - 1.0) / (k - 1)
    else:
        D = np.zeros(k)
    return -rem * (1.0 - D)

import numpy as np

def feature(item, bins, capacity):
    """Negative linear hinge of post-placement residue below the 25th-percentile room of the other open bins, normalised by that threshold."""
    b = np.asarray(bins, dtype=float)
    cap = float(capacity)
    k = b.shape[0]
    rooms = b[:-1] / cap                      # real open bins only; phantom excluded
    r = np.clip((b - item) / cap, 0.0, 1.0)   # post-placement residue fraction
    if rooms.shape[0] < 3:
        return np.zeros(k)
    q = float(np.quantile(rooms, 0.25))       # dead-room threshold from context
    if q <= 1e-6:
        return np.zeros(k)
    return -np.clip(q - r, 0.0, q) / q        # 0 at/above q, -1 at r=0, linear between

